mapper.select:
select
a.device_id,
a.device_name,
a.device_type,
a.device_code,
a.logical_type,
a.project_id,
a.relation_code,
a.create_time,
a.update_time,
a.remark
from t_cfg_device a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=VARCHAR}
 and a.device_name = #{deviceName, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=VARCHAR}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.logical_type = #{logicalType, jdbcType=VARCHAR}
 and a.project_id = #{projectId, jdbcType=BIGINT}
 and a.relation_code = #{relationCode, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.remark = #{remark, jdbcType=VARCHAR}

